package com.ruoyi.majorpilot.experience;
import com.fasterxml.jackson.databind.*;
import com.ruoyi.majorpilot.content.*;
import com.ruoyi.majorpilot.shared.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import org.springframework.mock.web.MockHttpServletRequest;
import static org.junit.jupiter.api.Assertions.*;

class ExecutionRulesTest {
    ObjectMapper mapper=new ObjectMapper();TaskContentRepository repository=new TaskContentRepository(mapper);
    TaskContent.Version version(String key){var bundle=repository.bundles().stream().filter(b->b.manifest().path("demoKey").asText().equals(key)).findFirst().orElseThrow();var m=bundle.manifest();return new TaskContent.Version(1,m.path("taskVersionId").asText(),"DEMO",null,key,"1.0.0",bundle.manifestSha256(),m);}
    TaskContentProvider provider=new TaskContentProvider(){public TaskContent.Version currentMajor(String ignored){throw new ApiException(404,"CONTENT_UNAVAILABLE");}public TaskContent.Version currentDemo(String key){return version(key);}public TaskContent.Version pinned(String id){return repository.bundles().stream().map(b->version(b.manifest().path("demoKey").asText())).filter(v->v.taskVersionId().equals(id)).findFirst().orElseThrow();}public TaskContent.Asset publicAsset(TaskContent.Version v,String key){var b=repository.bundles().stream().filter(x->x.manifestSha256().equals(v.manifestSha256())).findFirst().orElseThrow();byte[] bytes=repository.asset(b,key,true);return new TaskContent.Asset("application/json",bytes,TaskContentRepository.hash(bytes));}};
    @Test void allTwelveDemoConfigurationsProduceTheirActualGoldenResults(){var calculator=new FixedExecutionCalculator(provider,mapper);for(String demo:List.of("DEMO_TABLE","DEMO_COMPARE")){var v=version(demo);var op=v.manifest().path("operations").get(0);for(int multiplier=1;multiplier<=3;multiplier++)for(String include:List.of("ALL","FIRST_TWO")){var parameters=mapper.createObjectNode().put("multiplier",multiplier).put("include",include);var result=calculator.calculate(v,op,parameters);int count=include.equals("ALL")?4:2;int sum=demo.equals("DEMO_TABLE")?(count==4?26:7):(count==4?30:9);assertEquals(count,result.path("count").asInt());assertEquals(sum*multiplier,result.path("sum").asInt());assertEquals(sum*(double)multiplier/count,result.path("mean").asDouble());}}}
    @Test void arbitraryOperationsAndOutOfSchemaParametersAreRejected(){var calculator=new FixedExecutionCalculator(provider,mapper);var v=version("DEMO_TABLE");var op=v.manifest().path("operations").get(0);assertThrows(ApiException.class,()->calculator.calculate(v,op,mapper.createObjectNode().put("multiplier",4).put("include","ALL")));assertThrows(ApiException.class,()->calculator.calculate(v,op,mapper.createObjectNode().put("multiplier",1).put("include","ALL").put("url","https://untrusted.invalid")));var other=op.deepCopy();((com.fasterxml.jackson.databind.node.ObjectNode)other).put("engineType","SHELL");assertThrows(ApiException.class,()->calculator.calculate(v,other,mapper.createObjectNode()));}
    @Test void draftAndFinalRulesEnforceDeclaredFieldsWithoutCoercion(){var schema=version("DEMO_TABLE").manifest().path("steps").get(0).path("inputSchema");assertDoesNotThrow(()->ResponseRules.validate(schema,mapper.createObjectNode(),false));assertThrows(ApiException.class,()->ResponseRules.validate(schema,mapper.createObjectNode(),true));assertThrows(ApiException.class,()->ResponseRules.validate(schema,mapper.createObjectNode().put("acknowledged",false),true));assertThrows(ApiException.class,()->ResponseRules.validate(schema,mapper.createObjectNode().put("acknowledged","true"),true));}
    @Test void permissionFailureIsA403SafeEnvelopeNotGeneric500(){var request=new MockHttpServletRequest();var result=new ApiErrors().forbidden(request);assertEquals(403,result.getStatusCode().value());assertTrue(result.getBody().toString().contains("PERMISSION_DENIED"));assertFalse(result.getBody().toString().contains("AccessDeniedException"));}
    @Test void dependencyInvalidationIsTransitiveAndDoesNotTouchIndependentBranches()throws Exception{var graph=mapper.readTree("[{\"stepKey\":\"root\",\"dependencies\":[]},{\"stepKey\":\"left\",\"dependencies\":[\"root\"]},{\"stepKey\":\"right\",\"dependencies\":[\"root\"]},{\"stepKey\":\"leaf\",\"dependencies\":[\"left\"]},{\"stepKey\":\"independent\",\"dependencies\":[]}]");assertEquals(List.of("left","leaf"),RunService.dependentSteps(graph,"left"));assertEquals(List.of("root","left","right","leaf"),RunService.dependentSteps(graph,"root"));}
}
